def transform(grid):
    # Copy the input, then project each marked symbol upward with a stem
    # whose height is its fixed color-specific height from the demonstration.
    out = [row[:] for row in grid]
    r = next((i for i,row in enumerate(grid) if any(v in (2,8) for v in row)), None)
    if r is None:
        return out
    for c,v in enumerate(grid[r]):
        if v == 2:
            for rr in range(max(0,r-4), r):
                out[rr][c] = 1
            if r-4 >= 0: out[r-4][c] = 2
        elif v == 8:
            for rr in range(max(0,r-3), r):
                out[rr][c] = 1
            if r-3 >= 0: out[r-3][c] = 8
    return out
